// Confere se o orçamento tem as informações mínimas para enviar
const e = $json || {};
const falta = [];
const tel = String((e.cliente && e.cliente.telefone) || '').replace(/\D/g, '');
if (!e.cliente || !e.cliente.nome) falta.push('nome do cliente');
if (tel.length < 10) falta.push('telefone do cliente (inválido ou vazio: "' + ((e.cliente && e.cliente.telefone) || '') + '")');
if (!e.pdf_base64) falta.push('PDF do orçamento (pdf_base64 vazio)');
if (!e.orcamento || !e.orcamento.id) falta.push('id do orçamento');
if (falta.length) return { json: { ok: false, erro: 'Informações faltando: ' + falta.join(', ') } };
return { json: Object.assign({}, e, { ok: true }) };

// Confere se o número existe no WhatsApp
const r = $json || {};
const existe = r.numberExists === true || r.numberExists === 'true';
if (!existe || !r.chatId) return { json: { ok: false, erro: 'O número do cliente não existe no WhatsApp ou não foi possível resolvê-lo.' } };
return { json: Object.assign({}, r, { ok: true }) };

// Guarda o id da mensagem enviada e os dados do contato
const r = $('Enviar pelo WAHA').item.json;
const id = (r.id && (r.id._serialized || r.id.id)) ? (r.id._serialized || r.id.id) : (r.id || (r._data && r._data.id && r._data.id._serialized) || '');
const chatId = $('Resolver Numero WhatsApp').item.json.chatId;
const e = $('Exportar PDF da API').item.json;
const nome = (e.cliente && e.cliente.nome) || chatId.replace('@c.us', '');
// Marca o chat como "aguardando resposta do orçamento" (usado pelo agente de aceite)
const sd = $getWorkflowStaticData('global');
sd.aguardando = sd.aguardando || {};
sd.aguardando[chatId] = { orcamentoId: e.orcamento.id, numero: e.orcamento.numero || '', nome, telefone: chatId.replace('@c.us', ''), ts: Date.now() };
return { json: { messageId: String(id), chatId, nome } };

// ack >= 2: entregue ao aparelho do cliente (3/4: lida/ouvida)
const ack = Number(($json || {}).ack);
const nome = $('Extrair ID da Mensagem').item.json.nome;
const entregue = ack >= 2;
const texto = entregue
  ? 'Orçamento enviado para ' + nome + ' com sucesso ✅'
  : '⚠️ Orçamento enviado para ' + nome + ', mas o WhatsApp ainda não confirmou a entrega. Confira com o cliente.';
return { json: { entregue, texto } };

// Monta o aviso de erro (etapa: Buscar orçamentos pendentes no sistema)
const j = $json || {};
let motivo = j.erro;
if (!motivo && j.error) {
  const er = j.error;
  motivo = typeof er === 'string' ? er : [er.message, er.description, er.httpCode ? '(HTTP ' + er.httpCode + ')' : ''].filter(Boolean).join(' ');
}
if (!motivo) motivo = JSON.stringify(j).slice(0, 300);
let quem = '';
try { const x = $('Exportar PDF da API').item.json; quem = (x.orcamento && x.orcamento.numero ? ' | Orçamento ' + x.orcamento.numero : '') + (x.cliente && x.cliente.nome ? ' | Cliente: ' + x.cliente.nome : ''); } catch (e) {}
return { json: { texto: '❌ Falha no envio de orçamento' + quem + '\nEtapa: Buscar orçamentos pendentes no sistema\nMotivo: ' + motivo } };

// Monta o aviso de erro (etapa: Exportar PDF do orçamento)
