return { json: { texto: '❌ Falha no envio de orçamento' + quem + '\nEtapa: Resolver número no WhatsApp\nMotivo: ' + motivo } };

// Monta o aviso de erro (etapa: Validar número no WhatsApp)
const j = $json || {};
let motivo = j.erro;
if (!motivo && j.error) {
