return { json: { texto: '❌ Falha no envio de orçamento' + quem + '\nEtapa: Validar número no WhatsApp\nMotivo: ' + motivo } };

// Monta o aviso de erro (etapa: Enviar PDF pelo WhatsApp (WAHA))
const j = $json || {};
let motivo = j.erro;
if (!motivo && j.error) {
