return { json: { texto: '❌ Falha no envio de orçamento' + quem + '\nEtapa: Enviar PDF pelo WhatsApp (WAHA)\nMotivo: ' + motivo } };

// Monta o aviso de erro (etapa: Agente de IA (aceite do orçamento))
const j = $json || {};
let motivo = j.erro;
if (!motivo && j.error) {
  const er = j.error;
  motivo = typeof er === 'string' ? er : [er.message, er.description, er.httpCode ? '(HTTP ' + er.httpCode + ')' : ''].filter(Boolean).join(' ');
}
if (!motivo) motivo = JSON.stringify(j).slice(0, 300);
