try { const x = $('Exportar PDF da API').item.json; quem = (x.orcamento && x.orcamento.numero ? ' | Orçamento ' + x.orcamento.numero : '') + (x.cliente && x.cliente.nome ? ' | Cliente: ' + x.cliente.nome : ''); } catch (e) {}
return { json: { texto: '❌ Falha no envio de orçamento' + quem + '\nEtapa: Agente de IA (aceite do orçamento)\nMotivo: ' + motivo } };

// Monta o aviso de erro (etapa: Atualizar status no sistema (o PDF JÁ FOI enviado ao cliente; o orçamento pode ser reenviado em 5 min))
const j = $json || {};
let motivo = j.erro;
if (!motivo && j.error) {
  const er = j.error;
  motivo = typeof er === 'string' ? er : [er.message, er.description, er.httpCode ? '(HTTP ' + er.httpCode + ')' : ''].filter(Boolean).join(' ');
}
if (!motivo) motivo = JSON.stringify(j).slice(0, 300);
let quem = '';
try { const x = $('Exportar PDF da API').item.json; quem = (x.orcamento && x.orcamento.numero ? ' | Orçamento ' + x.orcamento.numero : '') + (x.cliente && x.cliente.nome ? ' | Cliente: ' + x.cliente.nome : ''); } catch (e) {}
return { json: { texto: '❌ Falha no envio de orçamento' + quem + '\nEtapa: Atualizar status no sistema (o PDF JÁ FOI enviado ao cliente; o orçamento pode ser reenviado em 5 min)\nMotivo: ' + motivo } };

// Só trata mensagens de clientes que estão aguardando resposta de um orçamento (compatível com Whaticket e WAHA)
const raw = $input.first().json.body || $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.aguardando = sd.aguardando || {};
const p = raw.payload || {};
const baileysMsg = raw.message || {};
const ev = raw.event || (raw.key ? 'message' : '');
const fromMe = Boolean((raw.key && raw.key.fromMe) ?? p.fromMe);
const nao = [{ json: { ok: false, responder: false } }];
if (ev !== 'message') return nao;
if (fromMe) return nao;
const rawFrom = String(p.from || (raw.key && raw.key.remoteJid) || '');
const chatId = rawFrom.replace('@s.whatsapp.net', '@c.us');
if (!chatId || chatId.includes('@g.us') || chatId.includes('status@broadcast')) return nao;
const ag = sd.aguardando[chatId] || sd.aguardando[rawFrom];
if (!ag) return nao;
if (Date.now() - ag.ts > 7 * 24 * 3600 * 1000) { delete sd.aguardando[chatId]; return nao; }
const mime = String((p.media && p.media.mimetype) || (p._data && p._data.mimetype) || (baileysMsg.audioMessage && baileysMsg.audioMessage.mimetype) || '');
const tp = String((p._data && p._data.type) || p.type || (baileysMsg.audioMessage ? 'ptt' : ''));
let text = String(p.body || baileysMsg.conversation || (baileysMsg.extendedTextMessage && baileysMsg.extendedTextMessage.text) || '').trim();
if (mime.startsWith('audio') || tp === 'ptt' || tp === 'audio' || Boolean(baileysMsg.audioMessage)) text = '[Cliente enviou um áudio que não pode ser ouvido. Peça para escrever.]';
else if ((p.hasMedia || baileysMsg.imageMessage || baileysMsg.documentMessage) && !text) text = '[Cliente enviou um arquivo/imagem]';
if (!text) return nao;
return [{ json: { ok: true, responder: true, chatId, text, orcamentoId: ag.orcamentoId, numero: ag.numero, nome: ag.nome, telefone: ag.telefone } }];

// Separa a resposta ao cliente da decisão (tags) e monta o aviso ao dono
const f = $('Filtrar Resposta').item.json;
let out = String($json.output || $json.text || '').trim();
let decisao = '';
let motivo = '';
const neg = out.match(/\[NEGADO:?\s*([^\]]*)\]/i);
if (neg) { decisao = 'negado'; motivo = (neg[1] || '').trim() || 'não informou o motivo'; }
else if (/\[ACEITO\]/i.test(out)) decisao = 'aceito';
const texto = out.replace(/\[NEGADO:?[^\]]*\]/gi, '').replace(/\[ACEITO\]/gi, '').replace(/\*\*/g, '*').trim() || 'Certo! Vou repassar para a equipe.';
let aviso = '';
if (decisao) {
  const sd = $getWorkflowStaticData('global');
  if (sd.aguardando) delete sd.aguardando[f.chatId];
  const dados = 'ID do orçamento: ' + f.orcamentoId + (f.numero ? ' (' + f.numero + ')' : '') + '\nContato: ' + f.telefone + '\nNome: ' + f.nome;
  aviso = decisao === 'negado'
    ? '❌ Orçamento NEGADO\n' + dados + '\nMotivo: ' + motivo
    : '✅ Orçamento ACEITO\n' + dados;
}
return { json: { chatId: f.chatId, texto, decisao, motivo, aviso, decidiu: !!decisao, orcamentoId: f.orcamentoId, telefone: f.telefone, nome: f.nome } };
